<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\Accessor\TemplateAssetCodeAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TemplateAssetCodeAccessor trait.
 *
 * Covers null default, string/VO assignment via withCode,
 * getCode/code accessors, and isCodeChanged with/without original.
 */
class TemplateAssetCodeAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withCode creates a new instance with the Code set
     * from a string value, and getCode returns the primitive string.
     */
    public function testWithCodeFromString(): void
    {
        // Arrange
        $holder = new ImplWithTemplateAssetCodeAccessorUnitTest();

        // Act
        $result = $holder->withCode('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getCode());
    }
    /**
     * Asserts that withcode has access to the value object
     * from a string value, and getCode returns the primitive string.
     */
    public function testWithCodeFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTemplateAssetCodeAccessorUnitTest();

        // Act
        $result = $holder->withCode('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->code()->value());
    }
    public function testChangedCode(): void
    {
        // Arrange
        $holder = new ImplWithTemplateAssetCodeAccessorUnitTest()->withCode('one');
        $original = $holder->withCode('one');
        $same = $holder->withCode('one');
        $modified = $holder->withCode('other');

        // Act
        $withSame = $original->isCodeChanged($same);
        $withDiferent = $original->isCodeChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTemplateAssetCodeAccessorUnitTest
{
    use TemplateAssetCodeAccessor;
}
